INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查询智能体定时任务','ai:schedule:read:api','api',p.id,'/v1/agent-console/schedules','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:read:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '创建智能体定时任务','ai:schedule:create:api','api',p.id,'/v1/agent-console/schedules','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:create:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '更新智能体定时任务','ai:schedule:update:api','api',p.id,'/v1/agent-console/schedules','PUT','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:update:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '启停智能体定时任务','ai:schedule:status:api','api',p.id,'/v1/agent-console/schedules/{id}/enabled','PUT','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:status:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '删除智能体定时任务','ai:schedule:delete:api','api',p.id,'/v1/agent-console/schedules/{id}','DELETE','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:delete:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查询智能体定时执行记录','ai:schedule:history:api','api',p.id,'/v1/agent-console/schedules/{id}/executions','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:history:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,status,sort,create_time,update_time,del_flag) SELECT '允许智能体无人值守执行','ai:schedule:execute','button',p.id,'active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:schedule:execute' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.code LIKE 'ai:schedule:%' AND p.status='active' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
